CREATE FUNCTION public.oa_control_authority_for(subject_arg uuid,role_arg text,cap_arg text,resource_arg text,connector_arg text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT jsonb_build_object('id',b.id,'version',b.version,'authEpoch',u.auth_epoch,'expiresAt',b.expires_at) FROM public.role_bindings b JOIN public.roles r ON r.tenant_id=b.tenant_id AND r.id=b.role_id JOIN public.users u ON u.tenant_id=b.tenant_id AND u.id=b.subject_id JOIN public.tenants t ON t.tenant_id=b.tenant_id WHERE b.tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND b.subject_id=subject_arg AND r.name=role_arg AND b.revoked_at IS NULL AND (b.expires_at IS NULL OR b.expires_at>now()) AND u.status='ACTIVE' AND t.status='ACTIVE' AND (b.scope_kind='TENANT' AND b.scope_id=b.tenant_id::text OR b.scope_kind='CAPABILITY' AND b.scope_id=cap_arg OR b.scope_kind='CONNECTOR' AND b.scope_id=connector_arg OR b.scope_kind IN ('RESOURCE','TASK','GROUP','USER') AND b.scope_id=resource_arg) ORDER BY (b.scope_kind='TENANT'),b.id LIMIT 1;
$$;
CREATE OR REPLACE FUNCTION public.oa_control_authority(subject_arg uuid,role_arg text,cap_arg text,resource_arg text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT public.oa_control_authority_for(subject_arg,role_arg,cap_arg,resource_arg,NULL); $$;
CREATE OR REPLACE FUNCTION public.oa_control_action_view(action_arg uuid,session_arg uuid,subject_arg uuid DEFAULT nullif(current_setting('app.actor_id',true),'')::uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT to_jsonb(a)||jsonb_build_object('task_id',t.id,'task_status',t.status,'cancel_requested_at',t.cancel_requested_at,'task_auth_epoch',t.auth_epoch,'current_auth_epoch',u.auth_epoch,'user_status',u.status,'tenant_status',org.status,'policy_version',org.policy_version,'audience',t.audience,'expires_text',to_char(t.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'run_status',r.status)
 FROM public.tool_actions a JOIN public.runs r ON r.tenant_id=a.tenant_id AND r.id=a.run_id AND r.owner_id=a.owner_id JOIN public.tasks t ON t.tenant_id=r.tenant_id AND t.id=r.task_id AND t.requester_id=a.owner_id JOIN public.users u ON u.tenant_id=a.tenant_id AND u.id=a.owner_id JOIN public.tenants org ON org.tenant_id=a.tenant_id
 WHERE a.tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid AND a.id=action_arg AND public.oa_control_session(subject_arg,session_arg)
 AND (a.owner_id=subject_arg OR EXISTS(SELECT 1 FROM public.approvals p WHERE p.tenant_id=a.tenant_id AND p.action_id=a.id AND p.approver_id=subject_arg AND p.workflow_version=1 AND public.oa_control_authority_for(p.approver_id,'ACTION_APPROVER',a.capability_id,a.resource_id,a.connector_id) IS NOT NULL) OR a.state IN ('UNKNOWN','APPLIED_UNVERIFIED') AND a.owner_id<>subject_arg AND public.oa_control_authority_for(subject_arg,'SECURITY_OPERATOR',a.capability_id,a.resource_id,a.connector_id) IS NOT NULL);
$$;
REVOKE ALL ON FUNCTION public.oa_control_authority_for(uuid,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oa_control_authority_for(uuid,text,text,text,text) TO oa_runtime;
ALTER TABLE control_events ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),ADD COLUMN version bigint NOT NULL DEFAULT 1 CHECK(version=1);
ALTER TABLE reconciliation_cases ADD COLUMN version bigint NOT NULL DEFAULT 1;
